class TestBtsStartUpViewPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.start_up_view = BtsStartUpViewPage()

    @patch('taf.ul.oam.selenium_coam.pages.bts_status.BtsStartUpViewModal')
    def test_reset_ald(self, bts_start_up_view_modal_mock):
        operation = bts_start_up_view_modal_mock.return_value
        operation.wait_for_start_up_view_modal_appear = mock.Mock()
        operation.get_bts_start_up_view_info = mock.Mock()
        operation.close = mock.Mock()

        self.start_up_view.get_bts_start_up_view_info('software')
        operation.wait_for_start_up_view_modal_appear.assert_called_once()
        operation.get_bts_start_up_view_info.assert_called_once()
        operation.close.assert_called_once()


