class TestCellsPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.cells_page = CellsPage()

    def test_get_cell_info(self):
        cell_index = 1
        xpath = 'test_xpath'
        info = {'key': 'value'}
        self.cells_page._get_cell_xpath_and_info_by_id = mock.MagicMock(return_value=(xpath, info))
        output = self.cells_page.get_cell_info(cell_index)
        self.cells_page._get_cell_xpath_and_info_by_id.assert_called_once()
        self.assertEqual(output, info)

    def test_lock_cell(self):
        xpath = 'test_xpath'
        info = {'key': 'value'}
        self.cells_page._get_cell_xpath_and_info_by_id = mock.MagicMock(return_value=(xpath, info))
        self.cells_page._view_panel.show_detail_panel = mock.Mock()
        self.cells_page._detail_panel.lock_cell = mock.Mock()

        self.cells_page.lock_cell(1)
        self.cells_page._get_cell_xpath_and_info_by_id.assert_called_once()
        self.cells_page._view_panel.show_detail_panel.assert_called_once()
        self.cells_page._detail_panel.lock_cell.assert_called_once()

    def test_unlock_cell(self):
        xpath = 'test_xpath'
        info = {'key': 'value'}
        self.cells_page._get_cell_xpath_and_info_by_id = mock.MagicMock(return_value=(xpath, info))
        self.cells_page._view_panel.show_detail_panel = mock.Mock()
        self.cells_page._detail_panel.unlock_cell = mock.Mock()

        self.cells_page.unlock_cell(1)
        self.cells_page._get_cell_xpath_and_info_by_id.assert_called_once()
        self.cells_page._view_panel.show_detail_panel.assert_called_once()
        self.cells_page._detail_panel.unlock_cell.assert_called_once()

    def test_get_cell_xpath_and_info_by_id(self):
        xpath_list = ['test_xpath']
        info = {'Global cell ID': '1'}
        self.cells_page._view_panel.get_cell_xpath_list = mock.Mock(return_value=xpath_list)
        self.cells_page._get_cell_info_by_xpath = mock.Mock(return_value=info)

        output = self.cells_page._get_cell_xpath_and_info_by_id(1)
        self.cells_page._view_panel.get_cell_xpath_list.assert_called_once()
        self.cells_page._get_cell_info_by_xpath.assert_called_once()
        self.assertEqual(output, ('test_xpath', info))

    def test_get_cell_info_by_xpath(self):
        xpath = 'test1'
        info = {'key': 'value'}
        self.cells_page._view_panel.show_detail_panel = mock.Mock()
        self.cells_page._detail_panel.get_detail_info_table = mock.Mock(return_value=info)

        output = self.cells_page._get_cell_info_by_xpath(xpath)
        self.cells_page._view_panel.show_detail_panel.assert_called_once()
        self.cells_page._detail_panel.get_detail_info_table.assert_called_once()
        self.assertEqual(output, info)

    def test_get_number_of_cells(self):
        self.get_number_of_cells = mock.MagicMock()
        self.get_number_of_cells()
        self.get_number_of_cells.get_number_of_cells()


